<template><view class="page"><view v-if="note"><view class="category">{{note.category}}　·　{{note.updatedAt}}</view><text class="title">{{note.title}}</text><view class="byline">作者　{{note.author}}　 ·　{{note.tags.map(t=>'#'+t).join('　')}}</view><view class="body">{{note.summary}}<text>\n\n每一个值得记下来的想法，都可以从这里开始。后续可继续补充文字、图片和附件内容。</text></view><view class="tools"><text @click="edit">✎　编辑</text><text @click="share">↗　分享</text><text @click="ai">✧　AI 整理</text></view></view><view v-else>找不到这条笔记</view></view></template>
<script setup>import {computed} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {notes} from '../../src/data/demo.js';import {ref} from 'vue';const id=ref('');onLoad(o=>id.value=o.id||'');const note=computed(()=>notes.find(n=>n._id===id.value));function edit(){uni.navigateTo({url:'/pages/editor/editor?id='+id.value})}function share(){uni.showToast({title:'分享功能待接入',icon:'none'})}function ai(){uni.showToast({title:'AI 功能预留中',icon:'none'})}</script>
<style scoped>.page{padding:28px 22px;background:white;min-height:100vh}.category{color:#536cf1;font-size:12px}.title{display:block;margin-top:17px;font-size:25px;font-weight:700;line-height:1.4}.byline{margin-top:13px;color:#999fa8;font-size:11px}.body{margin-top:30px;color:#444b55;font-size:15px;line-height:2;white-space:pre-wrap}.tools{position:fixed;left:16px;right:16px;bottom:22px;display:flex;justify-content:space-around;padding:15px;background:#f5f6fa;border-radius:16px;color:#536cf1;font-size:12px}</style>
